import { LocaleCatalog, LocaleCode } from './types';
import { buildCatalog, LocaleData } from './catalogEngine';

// Generated by `pnpm run build:locales` from src/language/locales/data/*.yaml
// - the hand-edited sources of truth for every locale/translation string.
import en from './generated/en.json';
import zhTw from './generated/zh-tw.json';
import zhCn from './generated/zh-cn.json';

const CATALOGS: Record<LocaleCode, LocaleCatalog> = {
  en: buildCatalog('en', en as LocaleData),
  'zh-tw': buildCatalog('zh-tw', zhTw as LocaleData),
  'zh-cn': buildCatalog('zh-cn', zhCn as LocaleData),
};

export function getCatalog(code: LocaleCode): LocaleCatalog {
  return CATALOGS[code];
}

/** Maps a VS Code display-language tag (vscode.env.language, e.g. "zh-cn", "zh-hant", "en-us") to one of our catalogs. Anything not recognizably Chinese falls back to English. */
export function resolveLocale(vscodeLanguage: string): LocaleCode {
  const lang = vscodeLanguage.toLowerCase();
  if (
    lang.startsWith('zh-tw') ||
    lang.startsWith('zh-hant') ||
    lang === 'zh-hk'
  ) {
    return 'zh-tw';
  }

  if (lang.startsWith('zh')) {
    return 'zh-cn';
  }

  return 'en';
}

export type {
  LocaleCatalog,
  LocaleCode,
  MnemonicProse,
  LocaleUi,
} from './types';
